	title 'Tool Locator         GS ROM 3.0'*****************************************************************			   **	   Tool Locator		   **			   **********************************************************************************************************************************			   **	Copyright (C) 1985-1989	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   *********************************************************************************************************************************** Change History** ?? ??? 86	Steven Glass** Original ROM release** ?? ??? 87	Steven Glass** Release for rom 2.0** ?? Oct 87	Steven Glass** Code that was in patch is integrated with ROM code for * first time.** ?? Feb 88	Steven Glass** Code converted to work with MAX** 23 Oct 88	Steven Glass** Added MessageByName.* Changed size of default TPT from 32 to 48.** 04 Nov 88	Steven Glass** Incorporated ResetUserPtr into TLStartup.** 07 Dec 88	Steven Glass** Changed code that calls bootinit routine so that it never calls* the memory manager boot init routine in ROM.** 19 Apr 89	Steven Glass** Add AppleIIForever Vector.** 26-Sep-90	Dave Lyons** Changed _SysDeathMgr to _SysFailMgr so this file will build* with current interfaces.** 6-Jun-91	Dave Lyons** Added SANEShutDown call at the beginning of TLShutDown.** 14-Sep-91	Dave Lyons** Made TLShutDown call QDAuxShutDown for some BONEHEADS who* are making ShutDownTools shut down the tool locator, and* *then* they are shutting down QuickDraw, which would have* shut down QDAux for them, but it's already gone.  (They* never asked for QDAux in the first place, but Window Mgr* loaded it so AlertWindow could use icons.)*****************************************************************	eject****************************************************************** Terminology** The Tool Pointer Table (TPT) is the table of pointers to the*        individual	Function Pointer Tables.* A Function Pointer Table (FPT) is the table of pointers to the*        to the individual functions in	a single tool set.* The Work Area Pointer Table (WAP Table) is the table of longs*        that are used by individual tools to store information*        without having access to permenent memory.  Tools usually*        keep the address of their direct page or a handle to some *        other data here.  The value of a tools WAP is always put*        in the A & X registers when a function of the tool is *        called.** Included in this file is the source to the tool dispatcher, * the tool init routine (SpecialInit) and the Tool Locator* calls.** Tool Locator has the following calls:**   1     TLBootInit*   2     TLApInit*   3     TLApShutDown*   4     TLVersion*   5     TLReset*   6     TLStatus*   9     GetTSPtr*   10    SetTSPtr*   11    GetFuncPtr*   12    GetWAP*   13    SetWAP*   14    LoadTools*   15    LoadOneTool*   16    UnloadOneTool*   17    TLMountVolume*   18    TLTextMountVolume*   19    SaveTextState*   20    RestoreTextState*   21    MessageCenter*   22    SetDefaultTPt************************************************************************************************************************************** How the Dispatching mechanism works:**     There are four entry points in Bank E0**         SystemDispatch*         Glue Dispatch*         UserDispatch*         Glue UserDispatch**     The only difference between the system and user entry*     points is that the pointers come out of different*     tables.**     The calling program must call these dispatchers in*     full native mode as follows:**         ldx #FuncNum*256+TSNum*         jsl Dispatch**     The difference between Dispatch and AutoPopDispatch is that*     there is one extra return address	on the stack at the*     time of the auto pop dispatch call.  The Dispatch entry point*     puts an extra	rtl address on the stack so that any parameters*     to a function	are the same depth in the stack no matter what*     entry point is used.*****************************************************************	blanks off	string asis	print push	print off	include 'all.macros'	include '::sys.equs.asm'	INCLUDE 'e16.memory'	include 'tl.equates.asm'	print pop	title ' Imported Addresses';-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT EndCall4	IMPORT EndCall8	IMPORT ErrOut4	IMPORT ErrOut8	IMPORT oBusyErr4	IMPORT oEndCall0	if RAMVersion=0 then	title ' Bank FE Vectors'	*****************************************************************BankFEVectors	PROC** These are the only public entry points into the bank FE* ROM.  All other entry is through the tool locator and * associated mechinisms.*** Inputs:*	none** Outputs:*	none** External Refs:	import SpecialInit	import InstallPeekerDA	import DAHandler	import ATSReset	import ATHReset	import STool	import AppleIIForever** Entry Points:*	none*	longa on	; mode	longi on** Change History** 03 Nov 88	STeven Glass & Joe Bo** Added a new vectors for entry into ADB tool.*****************************************************************	jml SpecialInit	jml InstallPeekerDA	jml DAHandler	jml ATHReset	; apple talks hard reset	jml ATSReset	; apple talks soft reset	jml STool	; Special entry into ADB tool added 3 Nov 88 by Joe and Steve	jml AppleIIForever	ENDP	title ' SpecialInit'*****************************************************************SpecialInit	proc ** This routine copies the pointer to the ROM based TPT to* and U_TPT pointers to RAM.** It also fixes the	RAM vectors in bank	E0 to point to this* code.** This is called and returns in 8 bit native mode.** Inputs:*	none** Outputs:*	none** External Refs:	import oErrOut	import ROM_TPT	import UserDummyTable	import Dispatch	import GluDispatch	import U_Dispatch	import U_GluDispatch	import iToolboxPatcher	import FixOSStackEntry** Entry Points:*	none*	longa on	; mode	longi on** Modification History**  17 May 86   Reset user pointers was being called before*              the memory manager was initialized.*  20 May 86   User	TPTPtr is now initialized before the TL*              boot	init call is made.**  04 Dec 86   I do	not make the WAPTPtr point to the top*              of the ROM any more.  I rely on the BootInit*              call	to set it correctly.**              Added JSL to RomToolHook, a vector in bank E1*              which installs any ROM tools in from the lower banks*              that	may be present.**  20 Jan 87   Oops, we found that some	fools were coming in in*              mixed native mode and relying on the code in	the dispatcher*              to clear the m-bit.  With great regret and trepidation*              I put the rep #$30 back into the dispatcher at all*              four	entry points.** 10 Jun 88    Init code uses oErrOut in this bank rather than bank*              FF for strip vectors.** 11 Oct 88    Added code to init the LLToolboxVector in bank $E1.*****************************************************************;----------------------------------------------------;; Fern calls me in Native mode with m and x set to 1;	rep #%00110000	longa on	longi on	ldx #14	; put the jump table inOtherLoop	lda >JumpTable,x	; ram	sta >RealDispatch,x	dex	dex	bpl OtherLoop;---------------------------------------------;; Put the pointers to the TPT and dummy	WAPT; into RAM.;	lda #ROM_TPT	sta >TPTPtr	lda #^ROM_TPT	sta >TPTPtr+2	sta >WAPTPtr+2	; set high word of this pointer*		; to prevent accidental access*		; to any softswitches	lda #UserDummyTable	; set this first time	sta >U_TPTPtr	lda #^UserDummyTable	sta >U_TPTPtr+2;--------------------------------------------------------;; Fix the end call vector;	ldx #6	; put the Strip vectors inLastLoop	lda >EndCallVector,x ; place	sta >ToBusyStrip,x	dex	dex	bpl LastLoop;-----------------------------------------------------------;; Init the LLToolboxVector;	lda >ToToolboxPatcher	sta >LLToolboxVector	lda >ToToolboxPatcher+2	sta >LLToolboxVector+2	jsl FixOSStackEntry;-----------------------------------------------------------;; Init all the tools.;	ldx #$0101	jsl RealDispatch	bcs SomethingsWrong	jsl RomToolHook	clcSomethingsWrong		; 	sep #%00110000	; set back to 8 bit	m and x for Fern	longa off	longi off	rtlJumpTable		; 	jml Dispatch	jml GluDispatch	jml U_Dispatch	jml U_GluDispatchEndCallVector		; 	jsl DecBusyFlg	jml oErrOutToToolboxPatcher	jml iToolBoxPatcher	ENDP	title 'U_Dispatch and U_GluDispatch'*****************************************************************TheU_Dispatcher	PROC ** Called with a JSL	after loading x with* the TSNum, FuncNum*** Called directly and makes the stack look as follows**       Real Return	Address*       TOS** The ToolNum FuncNum are in the x-reg.** Function expects*       Real Return	Address*       Another Return Address*       TOS** Inputs:*	x-reg  Call Number** Outputs:*	x-reg  Unchanged*	a-reg  trashed** External Refs:	IMPORT UserEntry	IMPORT AnRTL** Entry Points:	ENTRY U_Dispatch	ENTRY U_GluDispatch*	longa on	; mode	longi on*** Modification History**  04 Dec 86   SEG	   Removed code which returned error if*	   called from emulation.  This speeds*	   dispatch up by a	few cycles and saves*	   some code.** 20 Jan 87	Steven Glass** Started code with REP #30 because some dumb apps called tools* in mixed native mode and had luckily worked.** 09 Jul 88	Steven Glass** Andy Stadler pointed out that it takes fewer cycles to * build the stack frame by loads and pushes than it does * by subtracting and then loading and storing.*****************************************************************WAPTRef	equ 1	; 1    4TPTRef	equ WAPTRef+4	; 5    3RetADR1	equ TPTRef+3	; 8    4RetADR2	equ RetADR1+3	;11WorkSpace	equ RetADR2-WAPTRefFTableRef	equ TPTRefU_GluDispatch	phb	; push an extra byte on the stack and	bra GluJoin	; join the rest.U_Dispatch	pea AnRTL-1>>8	; put the address of an RTL on the stack	pea AnRTL-1<<8	; and one more byte too.GluJoin	rep #$30	; force full native mode	lda >U_TPTPtr	; put low word of TPT on stack	pha	; get middle and high bytes in place	lda >U_TPTPtr+1	sta 2,s	lda >U_WAPTPtr+2	; get WAPT ptr on stack	pha	lda >U_WAPTPtr	pha	tsc	; turn stack to d-page.	phd	tcd	bra UserEntry	ENDP	title 'Dispatch and GluDispatch'*****************************************************************TheDispatcher	PROC ** Called with a JSL	after pushing a word on the stack* which is the TSNum and the FuncNum*** Called directly and makes the stack look as follows**       Real Return	Address*       TOS** The ToolNum FuncNum are in the x-reg.** Function expects*       Real Return	Address*       Another Return Address*       TOS** Inputs:*	x-reg  Call Number** Outputs:*	a-reg  Low Word of WAP*	y-reg  High word of WAP*	x-reg  Unchanged** External Refs:*	none** Entry Points:	entry GluDispatch	entry Dispatch	entry UserENTRY	entry BadToolNumber	entry BadFunctionNumber	entry AnRTL	*	longa on	; mode	longi on*** Modification History** 04 Dec 86   SEG	   Removed code which returned error if*	   called from emulation.  This speeds*	   dispatch up by a	few cycles and saves*	   some code.*** 20 Jan 87	Steven Glass** Started code with REP #30 because some dumb apps called tools* in mixed native mode and had luckily worked.*** 09 Jul 88	Steven Glass** Andy Stadler pointed out that it takes fewer cycles to * build the stack frame by loads and pushes than it does * by subtracting and then loading and storing.*****************************************************************WAPTRef	equ 1	; 1    4TPTRef	equ WAPTRef+4	; 5    3RetADR1	equ TPTRef+3	; 8    4RetADR2	equ RetADR1+3	;11WorkSpace	equ RetADR2-WAPTRefFTableRef	equ TPTRefGluDispatch	phb	; push an extra byte on the stack and	bra GluJoin	; join the rest.Dispatch	pea AnRTL-1>>8	; put the address of an RTL on the stack	pea AnRTL-1<<8	; and one more byte too.GluJoin	rep #$30	; force full native mode	lda >TPTPtr	; put low word of TPT on stack	pha	; get middle and high bytes in place	lda >TPTPtr+1	sta 2,s	lda >WAPTPtr+2	; get WAPT ptr on stack	pha	lda >WAPTPtr	pha	tsc	; turn stack to d-page.	phd	tcdUserENTRY       ;----------------------------------------------;;    Now Check Tool	Set Number (still in x);;    To get the WAP	info and Function info from the;    memory we change the stack into zero page;	txa	pha	; save on stack for	later	and #$00FF	beq BadToolNumber	cmp [TPTRef]	bcs BadToolNumber;----------------------------------------------------;;    Tool number is	good.;	asl a	asl a	tay	lda [WAPTRef],y	; get entry in WAPT	for tool	tax	iny	iny	lda [WAPTRef],y	sta WAPTRef+2	stx WAPTRef	dey	; back y down 1	lda [TPTRef],y	; now get pointer to Tool's FPT	tax	dey	lda [TPTRef],y	sta TPTRef	stx TPTRef+1;-------------------------------------------------;;   Now we get the adr of the function out;   of the table;	lda 2,s	; now get func num in low byte of a	and #$00FF	; mask off high byte	beq BadFunctionNumber	cmp [FTableRef]	bcs BadFunctionNumber	asl a	asl a	tay	lda [FTableRef],y	tax	iny	lda [FTableRef],y	sta FTableRef+1	stx FTableRef;--------------------------------------------------;; Now if everything	went right, we pull	things off; the stack that we	need for the function.;;     DirectReg   2	bytes;     WAP         4	bytes  first two in	A last 2 in Y;     FuncAdr     3	bytes;	plx	; put func,tool num	in x for rich	pld	; restore direct register	pla	; WAP (low word)	ply	; WAP (high word)	rtl	; go to function!BadToolNumber		; 	ldx #BadTSNum	bra GoHomeBadFunctionNumber		; 	ldx #BadFuncNumGoHome	pla	; get TSNum & FuncNum off stack	pld	; restore d	tsc	; clean off crap from stack	clc	adc #WorkSpace	tcs	txa	sec	; set carryAnRTL		;       	rtl	ENDP	title ' Tables'*****************************************************************ROM_TPT	PROC ** The ROM tool pointer table is the table which contains* pointers to all the individual function pointer tables* (FPT's).** The first entry is a count.  It equals the number of tools* plus one.*** Inputs:*	none** Outputs:*	none** External Refs:	import TLTable		import MMCallTable		import MTCallTable		import CallTable		import DACallTable		import EMCallTable		import SchedulerCallTable		import SoundCallTable		import SKIFNCTBL		import SaneCallTable		import IMCallTable		import TextCallTable		import RDCallTable		import DummyTable		import LECallTable		import DialogCallTable 	import ScrapCallTable		import FMCallTable		import WindowCallTable	import MenuCallTable	import ListCallTable	import ControlCallTable** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************		DC.L (TheEnd-ROM_TPT)/4 	; number of active tools + 1	DC.L TLTable		; 1 Tool Locator	DC.L MMCallTable		; 2 Memory Manager	DC.L MTCallTable		; 3 misc tools	DC.L CallTable		; 4 Graphics Core	DC.L DACallTable		; 5 Desk Acc Mgr	DC.L EMCallTable		; 6 Event Manager	DC.L SchedulerCallTable	; 7 SchCallTable	DC.L SoundCallTable		; 8 SoundTable	DC.L SKIFNCTBL		; 9 FDB tool	DC.L SaneCallTable		; 10 (SANE)	DC.L IMCallTable		; 11 Integer math	DC.L TextCallTable		; 12 Text Tools	DC.L RDCallTable		; 13 Ram DISK	DC.L WindowCallTable	; 14 Window Manager	DC.L MenuCallTable		; 15 Menu Manager	DC.L ControlCallTable	; 16 Control Manager	DC.L DummyTable		; 17 Loader (not in rom)	DC.L DummyTable		; 18 QDAux	DC.L DummyTable		; 19 Print Manager	DC.L LECallTable		; 20 LineEdit	DC.L DialogCallTable 	; 21 Dialog Manager	DC.L ScrapCallTable		; 22 Scrap Manager	DC.L DummyTable		; 23 Standard File	DC.L DummyTable		; 24 	DC.L DummyTable		; 25 Note Synth	DC.L DummyTable		; 26 Note Seq	DC.L FMCallTable		; 27 Font Manager	DC.L ListCallTable		; 28 List Manager	DC.L DummyTable		; 29 A.C.E.	DC.L DummyTable		; 30	DC.L DummyTable		; 31	DC.L DummyTable		; 32 Midi	DC.L DummyTable		; 33	DC.L DummyTable		; 34	DC.L DummyTable		; 35	DC.L DummyTable		; 36	DC.L DummyTable		; 37	DC.L DummyTable		; 38	DC.L DummyTable		; 39	DC.L DummyTable		; 40	DC.L DummyTable		; 41	DC.L DummyTable		; 42	DC.L DummyTable		; 43	DC.L DummyTable		; 44	DC.L DummyTable		; 45	DC.L DummyTable		; 46	DC.L DummyTable		; 47	DC.L DummyTable		; 48TheEnd 	ENDP	ENDIF*****************************************************************TLTable	PROC ** This is the Function pointer Table (FPT) for the tool* locator tool set.*** Inputs:*	none** Outputs:*	none** External Refs:	import BootInit	import TLStartUp	import TLShutDown	import TLVersion	import TLReset	import TLStatus	import NotImp	import GetTSPtr	import SetTSPtr	import GetFuncPtr	import GetWAP	import SetWAP	import LoadTools	import LoadOneTool	import UnloadOneTool	import TLMountVolume	import TLTextMountVolume	import SaveTextState	import RestoreTextState	import MessageCenter	import SetDefaultTPT	import MessageByName	import StartupTools	import ShutdownTools** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	DC.L (TheEnd-TLTable)/4 ; call count + 1	DC.L BootInit-1	; 1	if RAMVersion=1 then	dc.L 0	dc.L 0	else	DC.L TLStartUp-1	; 2 app calls for init	DC.L TLShutDown-1	; 3 app calls to stop	ENDIF	DC.L TLVersion-1	; 4 version call	DC.L TLReset-1	; 5 reset call	DC.L TLStatus-1	; 6 status call	DC.L NotImp-1	; 7	DC.L NotImp-1	; 8	DC.L GetTSPtr-1	; 9	DC.L SetTSPtr-1	; 10	DC.L GetFuncPtr-1	; 11	DC.L GetWAP-1	; 12	DC.L SetWAP-1	; 13	DC.L LoadTools-1	; (14)	DC.L LoadOneTool-1	; (15)	DC.L UnloadOneTool-1 ; (16)	DC.L TLMountVolume-1 ; (17)	DC.L TLTextMountVolume-1 ; (18)	DC.L SaveTextState-1 ; (19)	DC.L RestoreTextState-1 ; (20);	DC.L MessageCenter-1 ; (21);	DC.L SetDefaultTPT-1 ; (22);	DC.L MessageByName-1 ; (23)	added 23 Oct 88	dc.L StartupTools-1	; (24)	added 08 nov 88	dc.L ShutdownTools-1 ; (25)	added 08 nov 88TheEnd		; 	ENDP*****************************************************************DummyTable	PROC EXPORT** This is a dummy call table with no pointers in it and a* count of zero.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	DC.L 0	ENDP*****************************************************************UserDummyTable	PROC EXPORT** This is a dummy user TPT with a length of 0 + 1 meaning no* tools in it.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	DC.L 1	ENDP	title ' TLBootInit'*****************************************************************BootInit	PROC** The boot init code must do the following:**     Initialize the memory manager*     Find out how many tool sets there	are in ROM*     Allocate enough space for the WAP	table for these tools*     Set the pointers in the WAP table	to zero*     Call the boot	initialization function of each of the*        other (besides tool locator and mm) tool sets in ROM.** Calling Sequence**     ldx #thenumbers*     jsl Dispatch*** Inputs:*	none** Outputs:*	none** External Refs:	import TLNewHandle	import SetUpUserWAPT** Entry Points:*	none*	longa on	; mode	longi on** Modification History** 05 Dec 86    SEG	    Changed Push #0	to pha, where all I	needed*	    was space for result.  Removed jsr to*	    ResetUserPtrs since they do not need to*	    be reset when they have not yet been changed.** 17 Jun 88	Steven Glass** Changed use of TLNewHandle for new reg usage.*****************************************************************	if RAMVersion=1 then 	rtl	ENDIFTPTRef	equ 1WAPTRef	equ TPTRef+4ZPSize	equ WAPTRef+4RTL1	equ ZPSizeRTL2	equ RTL1+3ParamSize	equ 0;----------------------------------------;; Get some space off the stack.;	tsc	; get stack pointer	sec	; subtract zpsize	sbc #ZPSize-1	tcs	; put back	phd	; save d	tcd	; make stack zp;----------------------------------------;; Initialize the memory manager.;	ldx #$0102	jsl $E10000	; initialize the memory manager	bcc cont1	jmp Diecont1		; 	jsl MMWarmStart1	; call mm mgr warm start vector;----------------------------------------;; use the number of	Tool Sets in ROM; to calculate how much space to; reserve for the WAPT.;	lda >TPTPtr	; look at the count	in the TPT	sta TPTRef	lda >TPTPtr+2	sta TPTRef+2	lda [TPTRef]	asl a	; multiply by four	asl a* Get enough memory	to store the number	of bytes in a	jsr TLNewHandle	bcc cont2	brl Diecont2	sta WAPTRef	; put handle on zp	stx WaptRef+2	lda [WAPTRef]	; and dereference it	tax	ldy #2	lda [WaptRef],y	sta WAPTRef+2	; store pointer on zp and in	sta >WAPTPtr+2	; permanent loc	stx WAPTRef	txa	sta >WAPTPtr;----------------------------------------;; Zero the new WAPT.;	lda [TPTRef]	asl a	asl a	tay	dey	; subtract 2	dey	lda #0	; zero the memoryZeroLoop	sta [WAPTRef],y	dey	dey	bpl ZeroLoop;----------------------------------------------------;; The system WAPT is set up and zeroed.; Now I must set up	the user WAPT.;	jsr SetUpUserWAPT	bcs die;---------------------------------------;; The WAPT is set up and zeroed.  The; individual tools can now be initialized; starting with number 3.	pea $0103	; put this call number on the stackInitLoop	lda 1,s	; get the current call number	tax	; put it on the stack	jsl $E10000	; make call	bcs CheckError	; check error codeKeepGoing	lda 1,s	; get call number back	inc a	; increment the tool number part	sta 1,s	; put it back on stack	bra InitLoop	; do it againCheckError	cmp #BadFuncNum	; bad func number but ts is there	beq KeepGoing	; so go to next	ldx #0	; assume no error	cmp #BadTSNum	; if error passed back is BadTSNum	beq NoError	; then there was no	error	tax	; return this error	codeNoError	pla	; clean stackDie		; 	pld	; restore zero page	tsc	; fix stack	clc	adc #ZPSize+ParamSize-1	tcs	txa	; put error code back in a	cmp #1	; compare to one to	fix carry	bcs NeverMind	jsl MMWarmStart2	; cannot return error;---------------------------------------------------;; Zero the pointer to the default TPT and call; set DefaultTPT.;	lda #0	sta >DefaultTPTPtr	sta >DefaultTPTPtr+2	_SetDefaultTPT	clcNeverMind	rtl	ENDP	title 'SetUpUserWAPT'*****************************************************************SetUpUserWAPT	PROC** Routine to set up the UserWAPT pointer.  This routine gets a* handle for four bytes and puts the dereferenced pointer in* U_WAPTPtr.** It also zeros the four bytes that are obtained.*** Inputs:*	none** Outputs:*	none** External Refs:	import TLNewHandle** Entry Points:*	none*	longa on	; mode	longi on** 17 Jun 88	Steven Glass** Changed use of TLNewHandle for new reg usage.*****************************************************************	lda #4	jsr TLNewHandle	bcs done	phx	; put handle back on stack	pha	phd	tsc	tcdHandle	equ 3	lda [Handle]	; and dereference it	tax	ldy #2	lda [Handle],y	sta Handle+2	sta >U_WAPTPtr+2	; and put in permanent loc	stx Handle	txa	sta >U_WAPTPtr	lda #0	; zero it	sta [Handle]	ldy #2	sta [Handle],y	pld	; restore d	pla	; clear stack	plaDone	rts	; carry is already clear.	ENDP	title 'TLStartAndStop'*****************************************************************TLStartAndStop	PROC EXPORT** All this does is to clear out the User Tool Pointers.*** Inputs:*	none** Outputs:*	none** External Refs:	import UnloadTools	import ResetUserPtrs** Entry Points:	EXPORT TLShutDown	EXPORT TLStartup*	longa on	; mode	longi on** Change History** 04 Nov 88	Steven Glass** Reset user pointer is now incorporated into this code.TLStartup* is also public so can be linked to patch file.*****************************************************************TLShutDown	_QDAuxShutDown	;added 14-Sep-91 DAL*** added 6-Jun-91 DAL -- force SANE off	_SANEShutDown*** end of 6-Jun-91 DAL	jsr UnloadToolsTLStartUp;-----------------------------------------------------------;; Reset User Pointer is now inline.  It is not called from; anywhere else.;	lda >U_TPTPtr	cmp #UserDummyTable	bne DumpHandle	lda >U_TPTPtr+2	cmp #^UserDummyTable	beq NothingToResetDumpHandle	pha	; space for result	pha	lda >U_TPTPtr+2	and #$00FF	; just in case the high word is trash.	pha	lda >U_TPTPtr	pha	_FindHandle	; note:  I do not check for errors	_DisposeHandle	; here because they	are very unlikely*		; moveover, If the handle cannot*		; be found, FindHandle returns*		; NIL and DisposeHandle won't dispose*		; anything when passed a NILResetIt		; 	lda #UserDummyTable	sta >U_TPTPtr	lda #^UserDummyTable	sta >U_TPTPtr+2	pha	; space for result	pha	lda >U_WAPTPtr+2	and #$00FF	pha	lda >U_WAPTPtr	pha	_FindHandle	; again I do not check for an error*		; here for the same	reasons as above	phd	; save d	tsc	; and make stack into direct page	tcdTheD	equ 1TheHandle	equ 3	ldy #4	; unlock the orig handle	lda [TheHandle],y	and #$7FFF	sta [TheHandle],y	PushLong #4	; resize the handle	pei TheHandle+2	pei TheHandle	_SetHandleSize	ldy #4	; lock the handle and deref it	lda [TheHandle],y	; putting result back in	ora #$8000	; U_WAPTPtr	sta [TheHandle],y	lda [TheHandle]	sta >U_WAPTPtr	dey	dey	lda [TheHandle],y	sta >U_WAPTPtr+2	pld	; restore direct	pla	; clear handle of stack	plaNothingToReset	jmp oEndCall0	ENDP	title 'TLReset'*****************************************************************TLReset	PROC** Resets the user pointers and calls the reset function * for every tool set.  If any of the tools returns an error, * this routine calls SystemDeath. If no tools return an error, * then this routine returns with no error.** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	ldx #$0502	; start by reseting	the memmgr	jsl $E10000	; this cannot fail?	pea 0	; put this flag on the stack	pea $0503	; the reset call is	5, start w/ts #3ResetLoop	lda 1,s	tax	jsl $E10000	bcs CheckErrorKeepGoing	lda 1,s	inc a	sta 1,s	bra ResetLoopCheckError	cmp #BadTSNum	; if the error is BadTSNum then we are	beq AllDone	; done, otherwise we die later so save*		; error code and keepgoing	cmp #BadFuncNum	; if the error is bad func num	beq KeepGoing	; then just a dummy	table	sta 3,s	; otherwise all is not kosher so	bra KeepGoing	; trash my indicator and continue.AllDone		; 	pla	; bad ts number so clean stack	pla	bne Die	_TLShutdown	jmp oEndCall0Die	pha	; put death info on	stack	PushLong #DeathString	ldx #$0101	; re-init all the tools	jsl $E10000	_SysFailMgr	; now dieDeathString	str 'Cannot Reset $'	ENDP	title 'TLStatus and TLVersion'*****************************************************************TLSTATUS	PROC** Returns true all the time since the TL is always active!*** Inputs:*	none** Outputs:*	StatusFlag : Boolean** External Refs:	import JoinVersion** Entry Points:*	none*	longa on	; mode	longi on*** Modification History** 05 Dec 86    SEG	    Put result at right place on stack** 24 Oct 88    SEG      This now shares code with TLVersion.*****************************************************************	lda #True	bra JoinVersion	ENDP*****************************************************************TLVersion	PROC EXPORT** Returns the version number of the tool locator.*** Inputs:*	none** Outputs:*	VersionNum : Word** External Refs:*	none** Entry Points:	entry JoinVersion*	*	longa on	; mode	longi on*** Modification History** 05 Dec 86    SEG	    Shares code with TLStatus (saving*	    3 bytes)** 24 Oct 88    SEG      This is now self contained so that it*	    can link by itself.  TLStatus shares*	    code with this instead of the otherway*	    around.*****************************************************************	lda #TLVersionNumberJoinVersion       	sta 7,s	jmp oEndCall0	ENDP	title 'GetTSPtr'*****************************************************************GetTSPtr	PROC** Returns the pointer to a Function Pointer Table in the* Tool Pointer Table.** Calling Sequence**        pha		; make room*        pha*        PushWord UserOrSystem*        PushWord TSNum*        _GetTSPtr*** Inputs:*	UserOrSystemFlag : word*	ToolNumber : word** Outputs:*	ToolPointer : long** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*** Change History** 23 Jan 86	SEG**     Should work now and is now written in more common style.*****************************************************************OrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TSNum	equ RTL2+3UserOrSystem	equ TSNum+2FTablePtr	equ UserOrSystem+2TPTRef	equ TSNum	; overwrite after reading	phd	; save this	tsc	; get stack pointer	tcd	; make stack zp	ldx TSNum	; get his in register	bit UserOrSystem	bmi UserPtrs	lda >TPTPtr	; get the TPTPtr to	zero page	sta TPTRef	lda >TPTPtr+1	bra GotPtrsUserPtrs	lda >U_TPTPtr	sta TPTRef	lda >U_TPTPtr+1GotPtrs	sta TPTRef+1	txa	and #$00FF	asl a	asl a	tay	lda [TPTRef],y	sta FTablePtr	iny	iny	lda [TPTRef],y	sta FTablePtr+2	jmp EndCall4	ENDP		title 'SetTSPtr'*****************************************************************SetTSPtr	PROC Export** Installs the pointer to a Function Pointer Table in the* Tool Pointer Table.** If the Tool Pointer Table is not in RAM, it* copies the table into RAM.** If there is not enough room in the TPT for the new entry,* the TPT is moved to a bigger chunk of	memory.  Likewise the* WAP Table is expanded.** If the new pointer table has zero entries, old entries are* moved from prior table to new table.** After the table is installed, the BootInit call of the* newly installed tool is made.** Possible Errors:**        Not enough	memory.*** Calling Sequence**        PushWord UserOrSystem*        PushWord FuncNumber*        PushPtr FuncTable*        _SetTSPtr**** Inputs:*        UserOrSystem : integer*        TSNumber :	integer*        FTablePtr : Ptr** Outputs:*	none** External Refs:	import GrowTables	import ResetTPTPtr	import TLNewHandle** Entry Points:*	none*	longa on	; mode	longi on*** Modification History** June 5, 1986   SEG**     Patches were not being installed properly.  On close*     inspection I discovered that I was Trashing the value*     of OldTSPtr as I moved it from the TPT Table to zero*     page.  This meant that whenever I	found a zero in the*     new table, I put garbage there instead of the real*     previous address.** System Disk 1.1 SEG**     I found that the case where we had to grow the existing*     table did not	work** 04 Dec 86 For ROM	2.0 SEG**     Saved a few bytes here and there turning PushLong #0*     to pha, pha when all we needed was space for results.** 17 Jun 88	Steven Glass** Changed use of TLNewHandle for new reg usage.** 24 Oct 88	Steven Glass** Changed the way this works for tools 1 and 5.  If the tool number is* 1 or 5 and it is a system tools, I don't install it.  This prevents* the tool locator and desk manager patch from system disks 1.0 - 3.1* from being installed.  It forces the use of the tools in ROM.** To patch tool 1 or 5 we have to set the SysOrUser flag to non* zero with high bit clear.  Zero will not work.*** 07 Dec 88	Steven Glass** Changed code that calls bootinit routine so that it never calls* the memory manager boot init routine in ROM.** 3/2/89	Mensch* Fixed a bug in detecting if the default table is being pointed at.* This call should now be able to run out of ROM*****************************************************************TPTRef	equ 1	; this is where I put pointer to*		; old TPTOldTSPtr	equ TPTRef+4	; this is pointer to old FPTNewTPTRef	equ OldTSPtr+4	; this is where I put pointer to*		; new TPTWAPTRef	equ NewTPTRef+4	; pointer to current WAPT*AHandle	equ WAPTRef+4	; this is temp storage for any*		; handle I need to deal with.ZPSize	equ AHandle+4RTL1	equ ZPSizeRTL2	equ RTL1+3FTablePtr	equ RTL2+3TSNum	equ FTablePtr+4UserOrSystem	equ TSNum+2ParamSize	equ 8;-----------------------------------------------;; First get some space for zero page.;	tsc	; get stack pointer	sec	; subtract zpsize	sbc #ZPSize-1	tcs	; put back	phd	; save d	tcd	; make stack zp;-----------------------------------------------------------;; In order to prevent system disks 1.0 through 3.1 from; patching out the tool locator and desk manager, we; look at the OS_Flag word.  Bit 2 of this word is FPatchLoaded.; It is set every time DeskShutdown is called.;; The first time DeskShutdown is called is right after the setup; files are loaded and just before the first application is about; to run.;; We use this bit to tell us whether or not to ignore attemps; to patch out the tool locator and desk manager.  Until; this bit is set, we will ignore all such attempts.;;	lda >OS_Flag	and #PatchLoadedBit	bne NoProblem	lda TSNum	cmp #1	beq EGads	cmp #5	bne NoProblemEGads	lda UserOrSystem	bne NoProblem	brl InitDoneNoProblem;-----------------------------------------------;; Move the right pointers to zero page depending; on whether this is a system or user call.;	bit UserOrSystem	bmi UserPtrs	lda >TPTPtr	; get the TPTPtr to	zero page	sta TPTRef	lda >TPTPtr+2	sta TPTRef+2	lda >WAPTPtr	sta WAPTRef	lda >WAPTPtr+2	bra GotPtrsUserPtrs	lda >U_TPTPtr	sta TPTRef	lda >U_TPTPtr+2	sta TPTRef+2	lda >U_WAPTPtr	sta WAPTRef	lda >U_WAPTPtr+2GotPtrs	sta WAPTRef+2;-----------------------------------------------;; check to see if we need to move the TPT;	lda TPTRef+2	and #$00FF	cmp #$00FE	beq NeedToMove;-----------------------------------------------------------;; Added the following for RAM basedc tool locator...;	lda TPTRef	cmp #UserDummyTable	bne NoNeedToMove	lda TPTRef+2	cmp #^UserDummyTable	bne NoNeedToMove	bra NeedToMove;-----------------------------------------------;; It is already in RAM so move the pointer to it; into NewTPTRef;NoNeedToMove		; 	lda TPTRef	sta NewTPTRef	lda TPTRef+2	sta NewTPTRef+2	bra TableInPlace;-----------------------------------------------;; It is still in ROM so we get space for it in; RAM and copy it over.;NeedToMove		; 	lda [TPTRef]	; The size I need is	asl a	; 4 * count	asl a	jsr TLNewHandle	sta AHandle	stx AHandle+2	lda [AHandle]	sta NewTPTRef	ldy #2	lda [AHandle],y	sta NewTPTRef+2	pei TPTRef+2	; copy the old to the new	pei TPTRef	pei NewTPTRef+2	pei NewTPTRef	lda [TPTRef]	asl a	asl a	PushWord #0	pha	_BlockMove	jsr ResetTPTPtrTableInPlace		; 	lda TSNum	cmp [TPTRef]	; see if TS with this number*		; already exists, or if we*		; have to grow the table	bcc NoGrow	jsr GrowTables	lda TSNumNoGrow		; ;-----------------------------------------------;; Get original pointer and replace it with; new pointer.;	asl a	; ts num is in a so	double it	asl a	; twice	tay	lda [TPTRef],y	sta OldTSPtr	lda FTablePtr	sta [NewTPTRef],y	iny	iny	; move whole long word SEG 5 Jun 86	lda [TPTRef],y	sta OldTSPtr+2	; +2 instead of 1 to move whole	lda FTablePtr+2	; long word SEG 5 Jun 86	sta [NewTPTRef],y;-----------------------------------------------;; Now go thru the new table looking at each; function pointer.	 For each function pointer; that is zero, we copy the old pointer	to the; new table.  This way a patch does not	have to; have pointers to functions that are not changing.;	lda [FTablePtr]	; get number of entries in new FuncTable	beq NoEntries	asl a	; times 4 for num bytes to deal with	asl a	tay	dey	deyPatchLoop	lda [FTablePtr],y	; look at high word	of entry	bne NewFunc1	; if not zero then must be new function	dey	; pointer so skip it.	dey	lda [FTablePtr],y	; look at low word of entry	bne NewFunc2	; if not zer then must be new function*		; pointer so skip it.	lda [OldTSPtr],y	; New entry was zero (both words)	sta [FTablePtr],y	; so copy the old entry to the new	iny	; entry.  (low word	then high word)	iny	lda [OldTSPtr],y	sta [FTablePtr],yNewFunc1	dey	; now need to dec 4	times	deyNewFunc2	dey	; if jumped here we	have already	dey	; decremented twice	before getting here	bpl PatchLoopNoEntries		; 	lda TSNum	; now make the boot	init call for this ts;-----------------------------------------------------------;; Special code to make AppleWorks GS work.  Never call the; BootInit code for the memory manager if the BootInit code; is still in ROM.;	cmp #$0002	; is it the memory manager?	bne @Continue	ldy #6	; if the address of  the init routine of the	lda [FTablePtr],y	; memory manager is in ROM, don't run it.  It	cmp #$00F0	; is not safe.	bcs InitDone	lda #$0002@Continue	ora #$0100	tax	bit UserOrSystem	bpl SysInit	jsl $E10008	bra InitDoneSysInit	jsl $E10000InitDone	ldx #0ErrorOut		; 	lda RTL1+4	sta RTL1+4+ParamSize	lda RTL1+2	sta RTL1+2+ParamSize	lda RTL1	sta RTL1+ParamSize	pld	; restore zero page	tsc	; fix stack	clc	adc #ZPSize+ParamSize-1	tcs	txa	cmp #1	rtl	ENDP	title 'ResetTPTPtr'*****************************************************************ResetTPTPtr	PROC** This routine copies the NewTPTRef back to the appropirate* master pointer.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************TPTRef	equ 1	; this is where I put pointer to*		; old TPTOldTSPtr	equ TPTRef+4	; this is pointer to old FPTNewTPTRef	equ OldTSPtr+4	; this is where I put pointer to*		; new TPTWAPTRef	equ NewTPTRef+4	; pointer to current WAPT*AHandle	equ WAPTRef+4	; this is temp storage for any*		; handle I need to deal with.ZPSize	equ AHandle+4RTL1	equ ZPSizeRTL2	equ RTL1+3FTablePtr	equ RTL2+3TSNum	equ FTablePtr+4UserOrSystem	equ TSNum+2	bit UserOrSystem	bmi UserPtrs2	lda NewTPTRef	; put new value into RAM pointer	sta >TPTPtr	lda NewTPTRef+2	sta >TPTPtr+2	bra doneUserPtrs2	lda NewTPTRef	; put new value into RAM pointer	sta >U_TPTPtr	lda NewTPTRef+2	sta >U_TPTPtr+2done	rts	ENDP	title 'GrowTables'*****************************************************************GrowTables	PROC** This is the tricky code that grows TPT and WAP.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************TPTRef	equ 1	; this is where I put pointer to*		; old TPTOldTSPtr	equ TPTRef+4	; this is pointer to old FPTNewTPTRef	equ OldTSPtr+4	; this is where I put pointer to*		; new TPTWAPTRef	equ NewTPTRef+4	; pointer to current WAPT*AHandle	equ WAPTRef+4	; this is temp storage for any*		; handle I need to deal with.ZPSize	equ AHandle+4RTL1	equ ZPSizeRTL2	equ RTL1+3FTablePtr	equ RTL2+3TSNum	equ FTablePtr+4UserOrSystem	equ TSNum+2	pha	; make room for result	pha	pei NewTPTRef+2	pei NewTPTRef	_FindHandle	pla	sta AHandle	pla	sta AHandle+2	pei AHandle+2	pei AHandle	_HUnlock	lda TSNum	; figure out how big we need it	and #$00FF	; use ts num	inc a	; plus 1	asl a	; times 4	asl a	PushWord #0	; push size on stack	pha	pei AHandle+2	pei AHandle	_SetHandleSize	pei AHandle+2	; relock it	pei AHandle	_HLock	lda [AHandle]	; dereference it	sta NewTPTRef	ldy #2	lda [AHandle],y	sta NewTPTRef+2	jsr ResetTPTPtr	; now fix the master pointer to TPT;-----------------------------------------------;; Since I grew the TPT, I also have to grow the; WAP.	pha	; make room for result	pha	pei WAPTRef+2	pei WAPTRef	_FindHandle	pla	sta AHandle	pla	sta AHandle+2	pei AHandle+2	pei AHandle	_HUnlock	lda TSNum	; calc size	and #$00FF	; ts num +1 times 4	inc a	asl a	asl a	PushWord #0	; push size on stack	pha	pei AHandle+2	pei AHandle	_SetHandleSize	pei AHandle+2	; relock it	pei AHandle	_HLock	lda [AHandle]	; dereference it	sta WAPTRef	ldy #2	lda [AHandle],y	sta WAPTRef+2	bit UserOrSystem	bmi UserPtrs	lda WAPTRef	; put new value into RAM pointer	sta >WAPTPtr	lda WAPTRef+2	sta >WAPTPtr+2	bra doneUserPtrs	lda WAPTRef	; put new value into RAM pointer	sta >U_WAPTPtr	lda WAPTRef+2	sta >U_WAPTPtr+2done		; ;-----------------------------------------------;; Now I must adjust	the TSCount and put	a pointer; to the dummy table in the new entries	of the; TPT and zeros in new entries of the WAP;	lda [NewTPTRef]	and #$00FF	asl a	asl a	tayDummyFill	lda #DummyTable	sta [NewTPTRef],y	lda #0	sta [WAPTRef],y	iny	iny	lda #^DummyTable	sta [NewTPTRef],y	lda #0	sta [WAPTRef],y	iny	iny	lda [NewTPTRef]	; bump counter in TPT	inc a	sta [NewTPTRef]	lda TSNum	; compare counter with last entry	and #$00FF	; counter should be	lastentry + 1	inc a	; when done	cmp [NewTPTRef]	beq LoopDone	bcs DummyFillLoopDone	rts	ENDP	title 'GetFuncPtr'*****************************************************************GetFuncPtr	PROC** Returns pointer to a specified Function.** Calling sequence:**         PushPtr 0		; make room for result*         PushWord UserOrSystem*         PushWord TSNum,FuncNum*         _GetFuncPtr**** Inputs:*	UserOrSystemFlag : word*	ToolAndFuncNumber : word** Outputs:*	FuncAdr : long** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************TPTRef	equ 1FTableRef	equ TPTREf+4OrigDirect	equ FTableRef+4RTL1	equ OrigDirect+2RTL2	equ RTL1+3TSNum	equ RTL2+3FuncNum	equ TSNum+1UserOrSystem	equ FuncNum+1FuncPtr	equ UserOrSystem+2	phd	; save this thing	pha	; put 8 bytes (four	words)	pha	pha	pha	tsc	; get stack pointer	tcd	; make stack zp	bit UserOrSystem	bmi UserPtrs	lda >TPTPtr	sta TPTRef	lda >TPTPtr+1	bra GotPtrUserPtrs	lda >U_TPTPtr	sta TPTRef	lda >U_TPTPtr+1GotPtr	sta TPTRef+1	lda TSNum	and #$FF	beq ABadTSNum	cmp [TPTRef]	bcc GoOn1ABadTSNum	ldx #xBadTSNum	bra ErrorOutGoOn1	asl a	asl a	tay	lda [TPTRef],y	sta FTableRef	iny	lda [TPTRef],y	sta FTableRef+1	lda FuncNum	and #$00FF	beq aBadFNum	cmp [FTableRef]	bcc GoOn2ABadFNum	ldx #xBadFuncNum	bra ErrorOutGoOn2	asl a	asl a	tay	lda [FTableRef],y	sta FuncPtr	iny	lda [FTableRef],y	sta FuncPtr+1	ldx #0ErrorOut	pla	; clear off the 8 bytes on stack	pla	pla	pla	jmp ErrOut4	; this goes out this way all the*		; time because for no error*		; x is zero	ENDP	title 'GetWAP'*****************************************************************GetWAP	PROC** Returns the pointer to work area of specified tool number*** Possible Errors:*     None.  I do not check for valid tool number!*** Calling Sequence**     PushPtr 0		; make room for result*     PushWord UserOrSystem*     PushWord TSNum*     _GetWAP*** Inputs:*	UserOrSystemFlag : word*	ToolNumber : word** Outputs:*	WAP value : LONG** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************OrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TSNum	equ RTL2+3UserOrSystem	equ TSNum+2WAP	equ UserOrSystem+2WAPTRef	equ TSNum	; overwrite after read	phd	; save direct	tsc	; get stack pointer	tcd	; make stack zp	ldx TSNum	; put this in x	bit UserOrSystem	bmi UserPtrs	lda >WAPTPtr	sta WAPTRef	lda >WAPTPtr+2	bra GotPtrsUserPtrs	lda >U_WAPTPtr	sta WAPTRef	lda >U_WAPTPtr+2GotPtrs	sta WAPTRef+2	txa	and #$00FF	asl a	; times 4	asl a	tay	; put it in y	lda [WAPTRef],y	; get low word of WAP	sta WAP	iny	; get high word of WAP	iny	lda [WAPTRef],y	sta WAP+2	jmp EndCall4	ENDP	title 'SetWAP'*****************************************************************SetWAP	PROC** Sets entry in WAP	table to specified value for specified* tool set.** Possible Errors:*        Bad Tool Set Number*** Calling Sequence**        PushPtr WAP*        PushWord UserOrSystem*        PushWord TSNum*        ldx*        jsl Dispatch**** Inputs:*	UserOrSystemFlag : word*	ToolNumber : word*	WAP value : LONG** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************TPTRef	equ 1OrigDirect	equ TPTRef+4RTL1	equ OrigDirect+2RTL2	equ RTL1+3WAP	equ RTL2+3TSNum	equ WAP+4UserOrSystem	equ TSNum+2WAPTRef	equ TSNum	; overwrite these	phd	; save this thing	pea 0	; put two words on stack	pea 0	tsc	; get stack pointer	tcd	; make stack zp	ldx TSNum	; get the TSNum	bit UserOrSystem	bmi UserPtrs	lda >WAPTPtr	sta WAPTRef	lda >WAPTPtr+2	sta WAPTRef+2	lda >TPTPtr	sta TPTRef	lda >TPTPtr+2	bra GotPtrsUserPtrs	lda >U_WAPTPtr	sta WAPTRef	lda >U_WAPTPtr+2	sta WAPTRef+2	lda >U_TPTPtr	sta TPTRef	lda >U_TPTPtr+2GotPtrs	sta TPTRef+2	txa	; get ts num back from x	and #$00FF	beq BadNum	cmp [TPTRef]	bcc ValidNumBadNum	ldx #xBadTSNum	pla	; clean up the stack	pla	jmp ErrOut8ValidNum		; 	asl a	; times 4	asl a	tay	; put it in y	lda WAP	sta [WAPTRef],y	iny	iny	lda WAP+2	sta [WAPTRef],y	pla	; clean up the stack	pla	jmp EndCall8	ENDP	title ' TLMemRoutines'*****************************************************************TLMemRoutines	PROC** Gets a handle of the size passed in the a-reg.  If GetMem* is used, attributes are passed from calling routine in* x-reg.  If TLNewhandle is used, attributes are TLAttributes.*** Inputs:*    a-reg  Size of	handle*    x-reg  attributes of handle (for GetMem only)** Outputs:*    a-reg  Low word of handle (or error)*    x-reg  high word of handle*    carry  set on error, clear on success** External Refs:*	none** Entry Points:	export TLGetMem	entry TLNewHandle*	longa on	; mode	longi on** Change History** 06 Oct 87    Steven Glass**    Added.** 17 Jun 88	Steven Glass** Combined this with TLNewHandle.  Code was almost identical* but duplicated.  By changing the calls to TLNewHandle to* use the a-reg and x-reg for output we could share code.*****************************************************************TLNewHandle	ldx #TLAttributesTLGetMem	pha	pha	pea $0000	pha	PushWord #TLUserID	phx	pha	pha	_NewHandle	bcs oops	pla	plx	rtsoops	plx	plx	rts	ENDP	EJECT********************************************************************************AppleIIForever	PROC** Description:	Wouldn't you like to know ...*** Inputs:	None** Outputs:	None** External Refs:** Entry Points:********************************************************************************Sound1	equ $FF1000Sound2	equ $FF1D00	php	rep #$30	pea 0	_SoundToolStatus	pla	bne @StartedAlready				pea $2000	_SoundStartup	bcs @Error@StartedAlready; Now play the sound!@Again	pea #$7FFF	_FFStopSound				sep #$20	; crank the volume a little!	Longa Off	lda >$E100CA	ora #$08	sta >$E100CA	rep #$20	Longa On	pea 1	PushLong #MyPBlock	_FFStartSound@Error	plp	rtlMyPBlock	dc.L Sound1	dc.W $000C	dc.W $00F6	; 5kHz 97	dc.W $0000	dc.W $000F	dc.L MyOTHERPBlock	dc.W $00FFMyOTHERPBlock	dc.L Sound2	dc.W $001F	dc.W $00F6	; 5kHz 97	dc.W $0000	dc.W $000F	dc.L 0	dc.W $00FF	EndP	END